T = []
def t(id, cat, title, objection, answer, verses, ccc, tags, related=()):
    T.append(dict(id=id, category=cat, title=title, objection=objection, answer=answer, verses=[dict(ref=r, why=w) for r, w in verses], ccc=list(ccc), tags=list(tags), related=list(related)))

C1='Scripture and Tradition'
t('sola-scriptura', C1, 'The Bible alone?', 'Christians should believe only what is in the Bible (sola scriptura). Tradition is man-made.',
 ["The Catholic Church holds that Scripture is the inspired word of God and the supreme written norm of faith, and also that God’s word reaches us in two linked ways: Sacred Scripture and Sacred Tradition. Both flow from the same source and are interpreted by the Church’s teaching office, the Magisterium, which serves the word and does not stand above it (Dei Verbum 10).",
  "The Bible itself does not teach that it alone is the rule. Paul tells the Thessalonians to hold fast to the traditions they were taught “by word of mouth or by letter” (2 Thessalonians 2:15), and calls the Church, not a book, “the pillar and bulwark of the truth” (1 Timothy 3:15). The New Testament books were written, collected and recognised as Scripture within the Church, and the list of books (the canon) is not itself a verse of Scripture. Second Timothy 3:16 says Scripture is useful for teaching and for equipping the man of God; it does not say it is the only authority.",
  "Catholics do not treat Tradition as adding new doctrines, but as the living handing on of what the apostles received, in worship, creeds and teaching."],
 [('2 Thessalonians 2:15','Hold fast to the traditions, by word of mouth or by letter'),('1 Timothy 3:15','The Church of the living God, the pillar and bulwark of the truth'),('2 Timothy 3:14-17','Scripture is inspired and useful for teaching'),('John 21:25','Not everything Jesus did was written down'),('2 Peter 1:20-21','No prophecy of Scripture is a matter of private interpretation')],
 [80,81,82,85,86,97,113],['Scripture','Tradition','Sola Scriptura','Magisterium'],['canon','church-authority'])

t('canon', C1, 'Why do Catholic Bibles have 73 books?', 'The Catholic Bible adds books to the Bible, the “Apocrypha”.',
 ["The Old Testament in Catholic Bibles includes seven books (Tobit, Judith, 1 and 2 Maccabees, Wisdom, Sirach, Baruch) and parts of Esther and Daniel that Protestants often leave out. These were in the Greek Old Testament (the Septuagint) that the first Christians, writing in Greek, mostly used and quoted. They were recognised as Scripture by the Church in the fourth and fifth centuries (the councils of Hippo, 393, and Carthage, 397, and the letter of Pope Innocent I, 405), and again at the Council of Florence and the Council of Trent.",
  "The shorter Hebrew canon fixed by Jewish teachers after the time of the apostles was not the Bible of the early Church; it was Luther in the sixteenth century who removed these books from the Old Testament. The New Testament contains allusions to some of them (for example Hebrews 11:35 and 2 Maccabees 7), and the practice of praying for the dead has a basis in 2 Maccabees 12:44-46. Catholics do not “add” books: the Church received 46 Old Testament and 27 New Testament books as the canon, and no one is able to point to a verse that lists the books of the Bible."],
 [('2 Maccabees 12:43-46','Prayer and sacrifice for the dead'),('Hebrews 11:35','Women received their dead by resurrection (cf. 2 Maccabees 7)'),('Wisdom 2:12-20','The righteous one mocked: read by the Church as a picture of Christ'),('Luke 24:44','The law, the prophets and the psalms')],
 [120,138],['Canon','Apocrypha','Deuterocanon','Septuagint'],['sola-scriptura'])

t('church-authority', C1, 'Did Jesus found a Church with authority?', 'Jesus never founded an institution; the Church is a human invention.',
 ["Jesus chose twelve apostles, gave them a share in his own authority (“Whoever listens to you listens to me”, Luke 10:16), the power to bind and loose (Matthew 18:18) and the Great Commission to teach and baptise all nations (Matthew 28:18-20). He promised that “the gates of hell shall not prevail” against his Church (Matthew 16:18) and that the Spirit of truth would guide the apostles into all truth (John 16:13).",
  "The Acts of the Apostles shows this structure at work: Matthias replaces Judas (Acts 1:15-26), the apostles settle a doctrinal dispute at the Council of Jerusalem (Acts 15), and Paul appoints elders (Acts 14:23, Titus 1:5). The Catholic Church teaches that the bishops are the successors of the apostles, and that the bishop of Rome, the Pope, is the successor of Peter. It also teaches that the Church’s authority is a service to the truth, for Christ is its head."],
 [('Matthew 16:18-19','On this rock I will build my Church'),('Matthew 18:15-18','Whatever you bind on earth shall be bound in heaven'),('Luke 10:16','Whoever listens to you listens to me'),('John 20:21-23','As the Father sent me, I send you; whose sins you forgive'),('Acts 15:1-29','The council of Jerusalem decides')],
 [551,552,553,861,862,880,881,882],['Church','Authority','Apostolic succession','Papacy'],['papacy','confession'])

t('papacy', C1, 'Is Peter the rock? The papacy', 'Peter was not the first Pope. The rock in Matthew 16 is Peter’s faith, or Christ himself.',
 ["Jesus gives Simon a new name, Cephas (Aramaic for rock, Greek Petros), and says, “You are Peter, and on this rock I will build my Church… I will give you the keys of the kingdom of heaven” (Matthew 16:18-19). The “keys” echo Isaiah 22:22, where the royal steward holds the keys of David’s house and “shall open, and none shall shut”: an office with successors, not just a person. Jesus also prays that Peter’s faith will not fail and tells him to strengthen his brothers (Luke 22:31-32), and charges him three times to “feed my sheep” (John 21:15-17).",
  "In Acts, Peter leads the choice of a replacement for Judas, preaches on Pentecost, and speaks first at the Council of Jerusalem. His name heads every list of the apostles. The Church has understood from earliest times that the bishop of Rome, where Peter died, inherits this ministry of unity: the Catechism says the Pope is “the perpetual and visible source and foundation of the unity both of the bishops and of the whole company of the faithful” (CCC 882). The Church also teaches that the Pope is infallible only when he solemnly defines a doctrine on faith or morals for the whole Church, not in everything he says."],
 [('Matthew 16:13-20','You are Peter, and on this rock'),('Isaiah 22:15-22','The keys of the house of David'),('Luke 22:31-32','Strengthen your brothers'),('John 21:15-19','Feed my lambs, tend my sheep'),('Acts 1:15-26','Peter leads the choice of an apostle'),('Galatians 1:18','Paul went to Jerusalem to see Cephas')],
 [552,553,881,882,891],['Papacy','Peter','Pope','Infallibility'],['church-authority'])
